/* Milestone configuration and entity presentation, layered over the existing registries. */
const measureDefaults={shipments:{unit:'shipment',plural:'shipments',verb:'Deliver',short:'ship',label:'Shipments closed',closeGap:5},attendance:{unit:'day',plural:'days',verb:'Work',short:'day',label:'Active days',closeGap:1},hours:{unit:'hour',plural:'hours',verb:'Log',short:'hr',label:'Hours logged',closeGap:2}};
function measure(id){const f=fby(id)||{};return {unit:f.unit||'unit',plural:f.unit||'units',verb:'Complete',short:'unit',label:f.name||id,closeGap:0,...measureDefaults[id],...f.display,integer:f.kind==='Integer',ratio:f.kind==='Percentage'};}
function milestonePersist(){try{sessionStorage.setItem('incentive-navigation-state',JSON.stringify({fields,configs,programs,entityMappings}));}catch{toast('Session storage is full. Your latest changes could not be saved.');}}
function upgradeMilestones(p){if(p.milestoneVersion)return p;p.legacyRewardDefinition={rows:structuredClone(p.rows),behaviour:p.behaviour,payoutType:p.payoutType};p.rows=p.rows.map(r=>({...r,flat:p.payoutType==='Lump Sum'?r.reward:0,rate:p.payoutType==='Variable'?r.reward:0,targets:Object.fromEntries([p.primary,...p.others].map(k=>[k,r.targets[k]??0]))}));p.slabBehaviour=p.behaviour==='tiered'?'ALL_CROSSED':'TOP_ONLY';p.rateBehaviour=p.behaviour==='all'?'ALL_UNITS':'THIS_SLAB';p.milestoneVersion=1;return p;}
programs.forEach(upgradeMilestones);nextProgramId=Math.max(nextProgramId,...programs.map(p=>Number(p.id)+1));
const milestoneBlank=blankProgram;
blankProgram=function(type=0){const p=upgradeMilestones(milestoneBlank(type));p.rows=[{targets:Object.fromEntries([p.primary,...p.others].map(k=>[k,0])),flat:0,rate:0}];p.slabBehaviour='TOP_ONLY';p.rateBehaviour='ALL_UNITS';return p;};
function rewardMode(p){return p.rows.some(r=>r.flat>0)?p.rows.some(r=>r.rate>0)?'both':'flat':p.rows.some(r=>r.rate>0)?'rate':'both';}
function presentation(p){return {...backendPresentation.shipment,...p.presentation,...configs[p.type]?.presentation};}
function modeWords(p){return p.slabBehaviour==='ALL_CROSSED'?'Every milestone crossed':'Top milestone only';}
programBehavior=modeWords;
function rewardPhrase(p,r){const m=measure(p.payout),flat=r.flat?currency(r.flat):'',rate=r.rate?`${currency(r.rate)} per ${m.unit}`:'';return flat&&rate?flat+(p.rateBehaviour==='ALL_UNITS'?` and ${currency(r.rate)} on every eligible ${m.unit}`:', then '+rate):flat||rate||'No reward';}
function periodWords(p){return p.evaluation==='Daily'?'Today':p.evaluation==='Weekly'?'This week':p.evaluation==='Monthly'?'This month':'This programme';}
function milestoneFormula(p){if(!p.rows.some(r=>r.rate))return p.slabBehaviour==='ALL_CROSSED'?'Payout = sum of qualifying lump sums':'Payout = highest qualifying lump sum';return p.slabBehaviour==='ALL_CROSSED'?'Payout = sum of each qualifying lump sum + rate × units in its band':`Payout = lump sum + rate × ${p.rateBehaviour==='ALL_UNITS'?measure(p.payout).plural:'('+measure(p.payout).plural+' − milestone threshold)'}`;}
formulaText=milestoneFormula;
function incentiveCaps(c){if(c?.earningCaps)return c.earningCaps;if(c&&Object.hasOwn(c,'earningCap'))return {Daily:c.earningCap,Weekly:c.earningCap,Monthly:c.earningCap,Custom:c.earningCap};return {Daily:5000,Weekly:20000,Monthly:50000,Custom:null};}
function incentiveCap(p){return incentiveCaps(configs[p.type])[p.evaluation]??null;}
calculate=function(p){upgradeMilestones(p);return MilestoneEngine.calculate({...p,earningCap:incentiveCap(p)},p.metrics,evaluateRules('fieldFilters',ensureRules(p).fieldFilters,p.metrics));};
function milestoneErrors(p){const c=configs[p.type];if(!c)return ['Select an incentive type.'];const a=[];if(!p.name.trim())a.push('Enter an incentive name.');if(!p.start||(p.end&&p.start>p.end))a.push('Enter a start date and an end date on or after it, or leave the end date empty.');if(p.evaluation==='Weekly'&&p.start&&p.end&&((Date.parse(p.end)-Date.parse(p.start))/86400000+1)%7!==0)a.push('Weekly incentives must cover complete 7-day periods, including the start and end dates (for example, Monday to Sunday).');if(![c.primary,...c.others].includes(p.primary))a.push('Choose an available main parameter.');if(![c.primary,...c.others,c.payout].includes(p.payout))a.push('Choose an available payout parameter.');if(p.rows.some(r=>r.rate>0)&&!c.payouts.includes('Variable'))a.push('Rates are not enabled for this incentive type.');if(p.rows.some(r=>r.flat>0)&&!c.payouts.includes('Lump Sum'))a.push('Lump sums are not enabled for this incentive type.');if(!p.rows.some(r=>r.flat||r.rate))a.push('Enter a lump sum or rate for at least one milestone.');const f=validateFilterRules(p);if(f)a.push(f);return [...a,...MilestoneEngine.validate(p,measure).errors];}
programValidation=p=>milestoneErrors(upgradeMilestones(p))[0]||'';
function normalizeMilestoneMode(p){if(!p.rows.some(r=>r.rate))return;if(p.payout!==p.primary){p.rateBehaviour='ALL_UNITS';p.slabBehaviour='TOP_ONLY';}else if(p.slabBehaviour==='ALL_CROSSED')p.rateBehaviour='THIS_SLAB';else if(p.rows.every(r=>!r.flat))p.rateBehaviour='ALL_UNITS';}
function chooseRewardMode(p,mode){for(const r of p.rows){r.hiddenReward||={};for(const k of ['flat','rate']){const show=mode==='both'||mode===k;if(!show){r.hiddenReward[k]=r[k];r[k]=0;}else if(!r[k]&&r.hiddenReward[k]!=null){r[k]=r.hiddenReward[k];delete r.hiddenReward[k];}}}p.editRewardMode=mode;normalizeMilestoneMode(p);}
function miniSelect(label,id,value,items){return `<label class="label" for="${id}">${label}</label><select id="${id}">${items.map(o=>`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`;}
function behaviorChoice(group,value,label,desc,active,disabled=false){return `<button type="button" class="ms-choice ${active?'selected':''}" data-ms-choice="${group}" data-value="${value}" aria-pressed="${active}" ${disabled?'disabled':''}><strong>${label}</strong><span>${desc}</span></button>`;}
function generatedConditions(p){return [
 ['evaluation',p.evaluation==='Custom'?'Calculated for the whole programme.':`Calculated ${p.evaluation.toLowerCase()}; progress resets each period.`],
 ...(p.end?[['dates',`${dateLabel(p.start)} – ${dateLabel(p.end)}.`]]:[]),
 ['milestones',p.slabBehaviour==='ALL_CROSSED'?'Every qualifying milestone pays its own lump sum and rate band.':'Only the highest qualifying milestone pays; earlier rewards are replaced.'],
 ...(p.rows.some(r=>r.rate)?[['rate',p.rateBehaviour==='ALL_UNITS'?`The rate applies to all eligible ${measure(p.payout).plural} from zero.`:'The rate counts units above the milestone threshold. The current band continues until the next milestone qualifies.']]:[]),
 ['gates',`Every stage needs ${[p.primary,...p.others].map(k=>measure(k).label).join(' AND ')}.`],
 ['filters',fieldFilterCopy(p)||'All records included by the registered measures. No additional field filters.']
 ];}
function conditionCopy(p,key,fallback){return p.conditionCopy?.[key]?.trim()||fallback;}
function incentiveCapCopy(p){const cap=incentiveCap(p);return cap==null||cap===''?'':'Maximum incentive per user: '+currency(cap)+' per '+({Daily:'day',Weekly:'week',Monthly:'month',Custom:'programme'}[p.evaluation]||'evaluation period')+'. Includes lump sum and rate earnings.';}
function conditionMarkup(p){return '<ul>'+(incentiveCapCopy(p)?'<li>'+esc(incentiveCapCopy(p))+'</li>':'')+generatedConditions(p).map(([k,t])=>`<li>${esc(conditionCopy(p,k,t))}</li>`).join('')+(p.explanationBullets??configs[p.type]?.explanationBullets??[]).filter(t=>t.trim()).map(t=>`<li>${esc(t)}</li>`).join('')+'</ul>';}
function explanationRows(p,admin=false){p.explanationBullets??=structuredClone(admin?[]:configs[p.type]?.explanationBullets||[]);return `<div class="ms-copy-lines">${p.explanationBullets.map((t,i)=>`<div class="ms-copy-line"><input type="text" data-explanation-line="${i}" value="${esc(t)}" aria-label="Explanation ${i+1}" placeholder="Explanation"><button type="button" class="link" data-remove-explanation="${i}" aria-label="Remove explanation ${i+1}">×</button></div>`).join('')}</div><button type="button" class="link" id="msAddExplanation">+ Add new line item</button>`;}
function conditionEditor(p){return `<section class="panel"><div class="panel-head"><h2>Conditions shown to the entity</h2></div><div class="panel-body"><p class="quiet">Edit the wording without changing calculation rules.</p>${generatedConditions(p).map(([k,t])=>`<label class="label">${{evaluation:'Evaluation',dates:'Dates',milestones:'Milestones',rate:'Rate',gates:'Required parameters',filters:'What counts'}[k]}<input type="text" data-condition-copy="${k}" placeholder="${esc(t)}" value="${esc(conditionCopy(p,k,t))}"></label>`).join('')}<label class="label">Additional explanation</label>${explanationRows(p)}</div></section>`;}
function bindExplanationRows(p){document.querySelectorAll('[data-explanation-line]').forEach(el=>el.oninput=()=>{p.explanationBullets[Number(el.dataset.explanationLine)]=el.value;});document.querySelectorAll('[data-remove-explanation]').forEach(el=>el.onclick=()=>{p.explanationBullets.splice(Number(el.dataset.removeExplanation),1);render();});const add=document.getElementById('msAddExplanation');if(add)add.onclick=()=>{p.explanationBullets.push('');render();document.querySelector('[data-explanation-line="'+(p.explanationBullets.length-1)+'"]')?.focus();};}
function bindConditionEditor(p){document.querySelectorAll('[data-condition-copy]').forEach(el=>el.oninput=()=>{p.conditionCopy||={};p.conditionCopy[el.dataset.conditionCopy]=el.value;});bindExplanationRows(p);}
function applyAdminParameters(p){const c=configs[p.type];if(!c)return p;const changed=p.primary!==c.primary||p.payout!==c.payout;p.primary=c.primary;p.payout=c.payout;p.others=[...c.others];for(const r of p.rows)for(const k of [p.primary,...p.others])if(r.targets[k]==null)r.targets[k]=0;if(changed)normalizeMilestoneMode(p);return p;}
managerForm=function(){const p=applyAdminParameters(upgradeMilestones(programEdit)),c=configs[p.type],ps=[p.primary,...p.others],mode=p.editRewardMode||rewardMode(p),hasRate=mode!=='flat',m=measure(p.payout),cross=p.payout!==p.primary;return `<div class="titlebar"><div><button class="link" id="backPrograms">← Programs</button><h1>${p.id?'Edit incentive':'Create incentive'}</h1></div><span class="badge">${esc(managerMapping().entity)}</span></div>${managerContext()}<div class="ms-layout"><div class="ms-form"><section class="panel"><div class="panel-head"><h2>Programme</h2></div><div class="panel-body"><div class="group"><label class="label" for="pName">Incentive name</label><input id="pName" type="text" data-ms-program="name" value="${esc(p.name)}"></div><div class="grid group"><div>${miniSelect('Incentive type','msType',String(p.type),managerConfigIndices().map(i=>({id:String(i),name:configs[i].name})))}</div><div>${miniSelect('Evaluation period','msEvaluation',p.evaluation,['Daily','Weekly','Monthly','Custom'].map(x=>({id:x,name:x==='Custom'?'Whole programme':x})))}</div></div><div class="grid"><label class="label">Start date<input type="date" data-ms-program="start" value="${esc(p.start)}"></label><label class="label">End date (optional)<input type="date" data-ms-program="end" value="${esc(p.end||'')}"></label></div><p class="quiet">Leave the end date empty for an indefinite incentive.${p.evaluation==='Weekly'?' Weekly dates must cover multiples of 7 days, including both dates.':''}</p></div></section><section class="panel"><div class="panel-head"><h2>Parameters</h2></div><div class="panel-body">${incentiveCapCopy(p)?`<p class="notice">${esc(incentiveCapCopy(p))}</p>`:''}<div class="group"><label class="label">Main parameter</label><strong>${esc(measure(p.primary).label)}</strong><p class="quiet">Moves the milestone line and shows progress.</p></div><div class="group"><label class="label">Payout parameter</label><strong>${esc(measure(p.payout).label)}</strong><p class="quiet">What the rate multiplies.${cross?' Different from the main parameter: rates apply from the first unit.':''}</p></div><span class="quiet">Secondary parameters: ${p.others.map(k=>esc(measure(k).label)).join(', ')||'None'}. Every gate must be met to qualify.</span></div></section><section class="panel"><div class="panel-head"><h2>Milestones</h2></div><div class="panel-body"><label class="label">Reward type</label><div class="choices group">${[['flat','Lumpsum only'],['rate',`Per ${m.unit} only`],['both','Both']].filter(([k])=>k==='flat'?c.payouts.includes('Lump Sum'):k==='rate'?c.payouts.includes('Variable'):c.payouts.length>1).map(([v,t])=>`<button class="button ${mode===v?'ms-active':''}" data-reward-mode="${v}" aria-pressed="${mode===v}">${esc(t)}</button>`).join('')}</div><p class="quiet">Every target, lump sum and rate must be at least the previous milestone’s value. All parameter targets must be met to qualify.</p><div class="tablewrap"><table class="ms-table"><thead><tr><th></th>${ps.map(k=>`<th class="${k===p.primary?'ms-primary':''}">${esc(measure(k).label)} ≥</th>`).join('')}${mode!=='rate'?'<th>Lumpsum</th>':''}${hasRate?`<th>₹ / ${esc(m.unit)}</th>`:''}<th></th></tr></thead><tbody>${p.rows.map((r,i)=>`<tr><td>M${i+1}</td>${ps.map(k=>`<td><input type="number" min="0" step="${measure(k).integer?'1':'any'}" data-ms-row="${i}" data-ms-gate="${esc(k)}" value="${r.targets[k]??''}" aria-label="M${i+1} ${esc(measure(k).label)}"></td>`).join('')}${mode!=='rate'?`<td><input type="number" min="0" step="any" data-ms-row="${i}" data-ms-reward="flat" value="${r.flat}" aria-label="M${i+1} lump sum"></td>`:''}${hasRate?`<td><input type="number" min="0" step="any" data-ms-row="${i}" data-ms-reward="rate" value="${r.rate}" aria-label="M${i+1} rate"></td>`:''}<td><button class="link" data-ms-remove="${i}" aria-label="Remove M${i+1}" ${p.rows.length===1?'disabled':''}>×</button></td></tr>`).join('')}</tbody></table></div><button class="button" id="msAdd" >Add milestone</button></div></section><section class="panel"><div class="panel-head"><h2>Behaviour</h2></div><div class="panel-body"><label class="label">Which milestones pay</label><div class="ms-choice-grid group">${behaviorChoice('slabBehaviour','TOP_ONLY','Top milestone only','Only the highest qualifying milestone pays.',p.slabBehaviour==='TOP_ONLY')}${behaviorChoice('slabBehaviour','ALL_CROSSED','Every milestone crossed','Each qualifying milestone pays its lump sum and band.',p.slabBehaviour==='ALL_CROSSED',hasRate&&cross)}</div>${hasRate?`<label class="label">What the rate counts over</label><div class="ms-choice-grid group">${behaviorChoice('rateBehaviour','THIS_SLAB','From this milestone','Counts units above the milestone threshold.',p.rateBehaviour==='THIS_SLAB',cross||(mode==='rate'&&p.slabBehaviour==='TOP_ONLY'))}${behaviorChoice('rateBehaviour','ALL_UNITS',`From the first ${esc(m.unit)}`,'Counts every eligible unit, from zero.',p.rateBehaviour==='ALL_UNITS',p.slabBehaviour==='ALL_CROSSED')}</div>`:''}<div class="notice" id="msFormula">${esc(milestoneFormula(p))}</div></div></section><section class="panel"><div class="panel-head"><h2>Participants & filters</h2></div><div class="panel-body">${filterBuilder(p,'entityFilters')}${filterBuilder(p,'fieldFilters')}</div></section>${conditionEditor(p)}<div id="msValidation" aria-live="polite"></div><p class="quiet">Prototype: sample progress only. A 30-day historical dry run requires a live data connection.</p><div class="form-actions"><button class="button" id="msCoverage">Get estimated coverage</button><button class="button" id="msSaveDraft">Save draft</button><button class="button primary" id="msPublish">Make live in preview</button></div></div><div class="ms-preview"><div class="ms-preview-heading"><strong>Entity display</strong><span class="badge">Sample progress</span></div><div id="msLiveCard">${entityCard(p)}</div><details class="panel"><summary class="panel-head">Edit sample progress</summary><div class="panel-body">${[...new Set([...ps,p.payout,...ensureRules(p).fieldFilters.map(r=>r.field)])].map(k=>`<label class="label">${esc(fby(k)?measure(k).label:filterMeta('fieldFilters',k).label)}<input type="${fby(k)?'number':'text'}" step="any" data-ms-metric="${esc(k)}" value="${esc(p.metrics[k]??0)}"></label>`).join('')}<p class="quiet">Numeric progress represents records after field filters. No live query is executed.</p></div></details></div></div>`;};
const milestoneOldBindManager=bindManager;
bindManager=function(){milestoneOldBindManager();if(!programEdit)return;const p=programEdit;
 bindConditionEditor(p);
 document.querySelectorAll('[data-ms-program]').forEach(el=>el.oninput=()=>{p[el.dataset.msProgram]=el.value;refreshMilestonePreview();});
 document.getElementById('msType').onchange=e=>{const n=blankProgram(Number(e.target.value));Object.assign(n,{id:p.id,name:p.name,start:p.start,end:p.end,evaluation:p.evaluation,explanationBullets:p.explanationBullets,entityMappingId:managerMapping().id});programEdit=n;render();};
 document.getElementById('msEvaluation').onchange=e=>{p.evaluation=e.target.value;render();};
 document.querySelectorAll('[data-reward-mode]').forEach(b=>b.onclick=()=>{chooseRewardMode(p,b.dataset.rewardMode);render();});
 document.querySelectorAll('[data-ms-choice]').forEach(b=>b.onclick=()=>{p[b.dataset.msChoice]=b.dataset.value;normalizeMilestoneMode(p);render();});
 document.querySelectorAll('[data-ms-row]').forEach(el=>el.oninput=()=>{const r=p.rows[Number(el.dataset.msRow)],v=el.value===''?NaN:Number(el.value);if(el.dataset.msGate)r.targets[el.dataset.msGate]=v;else r[el.dataset.msReward]=v;refreshMilestonePreview();});
 document.querySelectorAll('[data-ms-remove]').forEach(b=>b.onclick=()=>{p.rows.splice(Number(b.dataset.msRemove),1);render();});
 document.getElementById('msAdd').onclick=()=>{const last=p.rows.at(-1);p.rows.push({targets:Object.fromEntries([p.primary,...p.others].map(k=>[k,(last?.targets[k]||0)+(k===p.primary?10:0)])),flat:0,rate:0});render();};
 document.querySelectorAll('[data-ms-metric]').forEach(el=>el.oninput=()=>{p.metrics[el.dataset.msMetric]=el.type==='number'?(el.value===''?NaN:Number(el.value)):el.value;refreshMilestonePreview();});
 document.getElementById('msCoverage').onclick=()=>openEstimatedCoverage(p);
 document.getElementById('msSaveDraft').onclick=()=>saveMilestoneProgram('Draft');document.getElementById('msPublish').onclick=()=>saveMilestoneProgram('Live');refreshMilestonePreview();
};
function refreshMilestonePreview(){if(!programEdit)return;const p=programEdit,errors=milestoneErrors(p),warnings=MilestoneEngine.validate(p,measure).warnings;document.getElementById('msValidation').innerHTML=[...errors.map(t=>`<div class="notice error">${esc(t)}</div>`),...warnings.map(t=>`<div class="notice ms-warning">${esc(t)}</div>`)].join('');document.getElementById('msPublish').disabled=!!errors.length;const coverageButton=document.getElementById('msCoverage');if(coverageButton){coverageButton.disabled=!!errors.length;coverageButton.title=errors.length?'Complete the incentive configuration to estimate coverage.':'';}document.getElementById('msFormula').textContent=milestoneFormula(p);document.getElementById('msLiveCard').innerHTML=entityCard(p);bindMilestoneDetails();}
function saveMilestoneProgram(status){const p=applyAdminParameters(programEdit),error=status==='Live'?programValidation(p):!p.name.trim()?'Enter an incentive name.':'';if(error){toast(error);return;}p.status=status;p.entityMappingId=managerMapping().id;if(!p.id)p.id=nextProgramId++;const saved=structuredClone(p);delete saved.editRewardMode;const i=programs.findIndex(x=>x.id===p.id);if(i<0)programs.push(saved);else programs[i]=saved;programEdit=null;milestonePersist();render();toast(status==='Live'?'Incentive is live in the entity preview.':'Draft saved.');}
function milestoneHero(p,r){const q=period(p);if(r.missing)return 'Progress is awaiting an update.';if(demoNow>q.programEnd)return 'Period closed. Calculated incentive: '+currency(r.total)+'.';if(demoNow<q.programStart)return 'Starts '+dateLabel(p.start)+'. View the stages and rewards.';if(r.missing)return 'Progress is awaiting an update.';if(!r.eligible)return 'View conditions to see what counts towards this incentive.';if(r.capReached)return 'You have reached the maximum incentive of '+currency(r.cap)+' for this evaluation period.';const next=p.rows[r.highest+1];if(!next){const top=p.rows[r.highest];return top?.rate?`You have completed all milestones, you are earning ${currency(top.rate)}/${measure(p.payout).unit}!`:'You have completed all milestones, keep going!';}
 const gaps=[p.primary,...p.others].filter(k=>p.metrics[k]<next.targets[k]).map(k=>{const m=measure(k),gap=Number((next.targets[k]-p.metrics[k]).toFixed(4));return m.ratio?`${gap} more percentage points in ${m.label}`:`${gap} more ${gap===1?m.unit:m.plural}`;});
 const reward=[next.flat?currency(next.flat):'',next.rate?`${currency(next.rate)}/${measure(p.payout).unit}${p.rateBehaviour==='ALL_UNITS'?' on all eligible units':' above this milestone'}`:''].filter(Boolean).join(' and ');
 return gaps.join(' and ')+(reward?' to get '+reward: ' to reach the next milestone')+'.';
}
function blockedMessage(p,r){const next=p.rows[r.highest+1];if(!next||p.metrics[p.primary]<next.targets[p.primary]||r.missing)return '';const missing=p.others.filter(k=>p.metrics[k]<next.targets[k]);return missing.length?`${measure(p.primary).label} target met. Still needed: `+missing.map(k=>`${measure(k).label} ≥ ${next.targets[k]} (current ${p.metrics[k]})`).join('; ')+'.':'';}
function stageState(p,r,i){if(r.matches[i])return p.slabBehaviour==='TOP_ONLY'&&i!==r.highest?'spent':'done';return !r.missing&&p.metrics[p.primary]>=p.rows[i].targets[p.primary]?'blocked':'open';}
function compactNum(n){return Math.abs(n)>=10000?new Intl.NumberFormat('en-IN',{notation:'compact',maximumFractionDigits:1}).format(n):String(n);}
function msCoin(p,state){return `<span class="ms-coin ${state}" role="img" aria-label="${{done:'Achieved',spent:'Achieved; superseded',blocked:'Secondary gate pending',open:'Upcoming'}[state]}">${state==='done'?'✓':state==='blocked'?'!':incentiveIcon(presentation(p),'milestone')}</span>`;}
function milestoneTimeline(p,r){const n=p.rows.length,from=Math.min(Math.max(0,r.highest),Math.max(0,n-3)),shown=p.rows.slice(from,from+3),x=p.metrics[p.primary]||0;const pos=i=>shown.length===1?50:100*(i+.5)/shown.length;let fill=0;if(shown.length){const floors=shown.map(s=>s.targets[p.primary]);if(x<floors[0])fill=floors[0]?pos(0)*Math.max(0,x)/floors[0]:pos(0);else{const i=floors.findLastIndex(v=>x>=v);fill=i===shown.length-1?pos(i):pos(i)+(pos(i+1)-pos(i))*(x-floors[i])/(floors[i+1]-floors[i]);}}
 const cols=`--ms-cols:${shown.length}`;
 return `<div class="ms-ladder" style="${cols}"><div class="ms-rewards">${shown.map(s=>`<div>${s.flat?`<strong>${esc('₹'+compactNum(s.flat))}</strong>`:''}${s.rate?`<small>+${currency(s.rate)}/${esc(measure(p.payout).short)}</small>`:''}${!s.flat&&!s.rate?'<small>—</small>':''}</div>`).join('')}</div><div class="ms-track-area"><div class="ms-track"><span style="width:${Math.max(0,Math.min(100,fill))}%"></span></div>${from>0&&p.slabBehaviour==='ALL_CROSSED'?'<span class="ms-earned-stub"></span>':''}<div class="ms-coins">${shown.map((s,i)=>msCoin(p,stageState(p,r,from+i))).join('')}</div></div><div class="ms-thresholds">${shown.map(s=>`<span>${esc(compactNum(s.targets[p.primary]))}</span>`).join('')}</div></div><p class="ms-axis">${esc(measure(p.primary).label)}</p>${n>shown.length?`<button class="ms-window" data-ms-details="${p.id??'draft'}">${from?`${from} ${p.slabBehaviour==='ALL_CROSSED'?'earned':'achieved'} earlier milestone${from===1?'':'s'}`:''}${from&&n>from+shown.length?' · ':''}${n>from+shown.length?`${n-from-shown.length} more milestones ahead`:''} — see all ${n}</button>`:''}<div class="ms-vertical-stages">${shown.map((s,i)=>`<div>${msCoin(p,stageState(p,r,from+i))}<span>${esc(measure(p.primary).label)} ≥ ${s.targets[p.primary]}<small>${esc(rewardPhrase(p,s))}</small></span></div>`).join('')}</div>`;
}
function earningBreakup(p,r){const terms=r.terms.filter(t=>t.amount||t.flat||t.rate),flat=terms.reduce((sum,t)=>sum+t.flat,0),lines=[];if(flat)lines.push(`Lump sum: ${currency(flat)}`);for(const t of terms)if(t.rate)lines.push(`${Number(t.quantity.toFixed(4))} ${measure(p.payout).plural} × ${currency(t.rate)} = ${currency(t.rate*t.quantity)}`);if(r.cap!==null&&r.cap!==undefined){if(r.uncappedTotal>r.total)lines.push('Before cap: '+currency(r.uncappedTotal)+'; maximum for this period: '+currency(r.cap)+'; earned: '+currency(r.total));else lines.push('Maximum for this period: '+currency(r.cap));}return lines.join(' · ')||'No reward earned for this period.';}
function incentiveEarnings(p,r,label){const upcoming=period(p).programStart>demoNow;return `<div class="ms-earnings"><span>${esc(label)} · Earnings</span><strong>${upcoming?currency(0):r.missing?'Awaiting data':currency(r.total)}</strong><small>${upcoming?'This incentive has not started yet.':r.missing?'Progress is not available for this period.':esc(earningBreakup(p,r))}</small></div>`;}
function incentiveCardMeta(p){const recurring=['Daily','Weekly','Monthly'].includes(p.evaluation);return `${recurring?`<span class="ms-period-tag">${esc(p.evaluation)}</span>`:''}${p.end||recurring?`<span>◷ ${esc(timeLeft(p))}</span>`:''}${p.end?`<span>▦ ${dateLabel(p.start)} – ${dateLabel(p.end)}</span>`:''}`;}

function filterSentence(r){const meta=filterMeta('fieldFilters',r.field),unit=fby(r.field)?measure(r.field).plural:fields.flatMap(f=>f.filterColumns||[]).find(f=>f.key===r.field)?.unit||'';const words={'<':'is less than','>':'is greater than','>=':'is greater than or equal to','<=':'is less than or equal to','=':'is equal to','!=':'is not equal to',BETWEEN:'is between',IN:'is one of','NOT IN':'is not one of'};const values=['IN','NOT IN'].includes(r.op)?(r.values||[]).join(', '):r.op==='BETWEEN'?`${r.value} and ${r.upper}${unit?' '+unit:''} (inclusive)`:`${r.value}${unit?' '+unit:''}`;return `${meta.label} ${words[r.op]||r.op} ${values}`;}
function filterGroups(p){const groups=[[]];for(const [i,r] of ensureRules(p).fieldFilters.entries()){if(i&&r.join==='OR')groups.push([]);groups.at(-1).push(filterSentence(r));}return groups.filter(g=>g.length);}
function fieldFilterCopy(p){return filterGroups(p).map(g=>g.length>1?'('+g.join(' AND ')+')':g[0]).join(' OR ');}
function fieldFilterMarkup(p){const groups=filterGroups(p);return groups.length?`<div class="ms-filter-groups">${groups.map(g=>`<div class="ms-filter-group">${g.map(esc).join('<div class="ms-filter-join">AND</div>')}</div>`).join('<div class="ms-filter-join">OR</div>')}</div>`:'<p>All records included by the registered measures. No additional field filters.</p>';}
// View selection is transient; it does not change a programme's rules or live metrics.
const incentivePeriodSelection=new Map();
const incentiveDay=86400000;
function incentiveDate(ms){return new Date(ms).toISOString().slice(0,10);}
function incentiveWindow(p){if(!['Daily','Weekly'].includes(p.evaluation)||!p.start)return null;const start=Date.parse(p.start),today=Date.parse(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(demoNow)),last=Math.min(today,p.end?Date.parse(p.end):today),step=p.evaluation==='Weekly'?7:1;if(last<start)return null;const latest=start+Math.floor((last-start)/(step*incentiveDay))*step*incentiveDay,key=String(p.id??'draft'),saved=Date.parse(incentivePeriodSelection.get(key)),chosen=Number.isFinite(saved)&&saved>=start&&saved<=latest?start+Math.floor((saved-start)/(step*incentiveDay))*step*incentiveDay:latest;return {start,last,step,latest,chosen,end:Math.min(chosen+(step-1)*incentiveDay,p.end?Date.parse(p.end):Infinity)};}
function selectedPeriodProgram(p){if(p._periodView)return p;const w=incentiveWindow(p);if(!w)return p;const key=incentiveDate(w.chosen),metrics=w.chosen===w.latest?p.metrics:p.metricsByPeriod?.[key]||Object.fromEntries(Object.keys(p.metrics).map(k=>[k,NaN]));return {...p,metrics,_periodView:true,_window:w};}
function selectedPeriodLabel(p){const w=p._window||incentiveWindow(p);if(!w)return periodWords(p);return w.step===7?dateLabel(incentiveDate(w.chosen))+' – '+dateLabel(incentiveDate(w.end)):w.chosen===w.latest&&incentiveDate(w.chosen)===new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata'}).format(demoNow)?'Today':dateLabel(incentiveDate(w.chosen));}
function incentivePeriodPicker(p){const w=p._window||incentiveWindow(p);if(!w)return '';const id=esc(String(p.id??'draft'));if(w.step===1)return `<label class="ms-period-picker">Date<input type="date" data-incentive-period="${id}" min="${p.start}" max="${incentiveDate(w.last)}" value="${incentiveDate(w.chosen)}"></label>`;let options='';for(let day=w.latest;day>=w.start;day-=7*incentiveDay){const end=Math.min(day+6*incentiveDay,p.end?Date.parse(p.end):Infinity);options+=`<option value="${incentiveDate(day)}" ${day===w.chosen?'selected':''}>${dateLabel(incentiveDate(day))} – ${dateLabel(incentiveDate(end))}</option>`;}return `<label class="ms-period-picker">Week<select data-incentive-period="${id}">${options}</select></label>`;}
function bindIncentivePeriodPickers(sheetId){document.querySelectorAll('[data-incentive-period]').forEach(el=>el.onchange=()=>{const p=detailsProgram(el.dataset.incentivePeriod);if(!p)return;const w=incentiveWindow(p),n=Date.parse(el.value);if(!w||!Number.isFinite(n)||n<w.start||n>w.last)return;incentivePeriodSelection.set(String(p.id??'draft'),el.value);if(programEdit)refreshMilestonePreview();else render();if(sheetId!=null)openMilestoneDetails(sheetId);});}
entityCard=function(p){upgradeMilestones(p);let r=calculate(p);const upcoming=period(p).programStart>demoNow;if(upcoming)r={...r,highest:-1,matches:p.rows.map(()=>false),total:0};const blocked=upcoming?'':blockedMessage(p,r),filter=fieldFilterCopy(p),display=presentation(p);return `<article class="ms-card"><button class="ms-card-head" data-ms-details="${p.id??'draft'}" aria-label="View ${esc(p.name||'incentive')} conditions"><span class="ms-card-icon">${incentiveIcon(display,'icon')}</span><span><strong>${esc(p.name||'Incentive name')}</strong><span class="ms-meta">${incentiveCardMeta(p)}</span></span><b>›</b></button><div class="ms-card-body"><p class="ms-hero">${esc(milestoneHero(p,r))}</p>${milestoneTimeline(upcoming?{...p,metrics:{...p.metrics,[p.primary]:0}}:p,r)}${blocked?`<div class="ms-blocked"><b>!</b> ${esc(blocked)}</div>`:''}<div class="ms-progress">${[p.primary,...p.others].map(k=>`<p>${esc(measure(k).label)}: <strong>${upcoming?'—':Number.isFinite(p.metrics[k])?p.metrics[k]:'Awaiting data'}</strong></p>`).join('')}</div>${incentiveEarnings(p,r,periodWords(p))}<button class="ms-window" data-ms-details="${p.id??'draft'}">View conditions</button></div></article>`;};
function detailsProgram(id){return programEdit&&(id==='draft'||String(programEdit.id)===String(id))?programEdit:programs.find(p=>String(p.id)===String(id));}
function openMilestoneDetails(id){const original=detailsProgram(id);if(!original)return;const p=selectedPeriodProgram(original);const r=calculate(p),d=document.getElementById('fieldDialog');d.className='details-dialog ms-sheet';d.setAttribute('aria-labelledby','dialogTitle');d.innerHTML=`<div class="panel-head"><h2 id="dialogTitle">Conditions</h2><button class="close" id="msCloseSheet" aria-label="Close conditions">×</button></div><div class="dialogbody"><h2>How it works</h2>${conditionMarkup(p)}${incentivePeriodPicker(p)}${incentiveEarnings(p,r,selectedPeriodLabel(p))}<h2>Incentive stages</h2><div class="ms-stage-list">${p.rows.map((s,i)=>`<div class="ms-stage">${msCoin(p,stageState(p,r,i))}<div><strong>${esc(rewardPhrase(p,s))}</strong><p>${[p.primary,...p.others].map(k=>`${esc(measure(k).label)} ≥ ${s.targets[k]} (current ${Number.isFinite(p.metrics[k])?p.metrics[k]:'unavailable'})`).join(' AND ')}</p><small>${{done:'Achieved',spent:'Achieved; superseded by a later stage',blocked:'Blocked: secondary gate pending',open:'Not yet reached'}[stageState(p,r,i)]}</small></div></div>`).join('')}</div></div>`;if(!d.open)d.showModal();document.getElementById('msCloseSheet').onclick=()=>d.close();bindIncentivePeriodPickers(id);}
function bindMilestoneDetails(){bindIncentivePeriodPickers();document.querySelectorAll('[data-ms-details]').forEach(b=>b.onclick=()=>openMilestoneDetails(b.dataset.msDetails));}
const milestoneBindEntity=bindEntity;bindEntity=function(){milestoneBindEntity();bindMilestoneDetails();};
const milestoneEntityView=entityView;entityView=function(){return milestoneEntityView().replace('No incentives to show.','No incentive is currently running for you.');};
const milestoneManagerList=managerList;managerList=function(){return milestoneManagerList().replace(/<td>(Lump Sum|Variable|Both)<small>/g,'<td>Milestone rewards<small>');};
// Admin-owned icons and governed copy metadata, persisted with the existing registry.
const milestoneAdminView=configView;
configView=function(){let html=milestoneAdminView();if(!html.includes('id="saveConfig"'))return html;draft.presentation={...backendPresentation.shipment,...draft.presentation};draft.measureDisplay||=Object.fromEntries(adminFields().map(f=>[f.id,structuredClone(measure(f.id))]));const iconPanel=`<section class="panel"><div class="panel-head"><h2>Entity card</h2></div><div class="panel-body"><div class="grid"><div><label class="label" for="msCardIcon">Incentive card icon</label><input type="file" id="msCardIcon" accept=".svg,image/svg+xml"><p class="quiet" id="msCardFile">${esc(draft.presentation.iconFile||'Upload an SVG file (up to 100 KB).')}</p></div><div><label class="label" for="msCoinIcon">Milestone coin icon</label><input type="file" id="msCoinIcon" accept=".svg,image/svg+xml"><p class="quiet" id="msCoinFile">${esc(draft.presentation.milestoneFile||'Upload an SVG file (up to 100 KB).')}</p><p class="quiet">Shown on upcoming milestones. Achieved and blocked states use ✓ and !.</p></div></div><div class="ms-icon-sample"><span id="msIconSample">${incentiveIcon(draft.presentation,'icon')}</span><strong>${esc(draft.name||'Incentive')}</strong><span class="ms-coin open" id="msCoinSample">${incentiveIcon(draft.presentation,'milestone')}</span></div></div></section><section class="panel"><div class="panel-head"><h2>Measure display words</h2></div><div class="panel-body"><p class="quiet">Shared registry labels used to generate entity copy. No programme-specific sentences.</p>${[...new Set([draft.primary,...draft.others,draft.payout])].filter(fby).map(k=>{const m=draft.measureDisplay[k]||measure(k);return `<details class="ms-measure"><summary>${esc(fname(k))}</summary><div class="grid">${[['label','Display name'],['unit','Singular unit'],['plural','Plural unit'],['short','Short unit (up to 4 characters)']].map(([key,label])=>`<label class="label">${label}<input type="${key==='closeGap'?'number':'text'}" ${key==='closeGap'?'min="0" step="any"':''} ${key==='short'?'maxlength="4"':''} data-ms-display="${esc(k)}" data-ms-word="${key}" value="${esc(m[key])}"></label>`).join('')}</div></details>`}).join('')}</div></section>`;html=html.replace('<div class="savebar">',iconPanel+`<section class="panel"><div class="panel-head"><h2>Incentive cap</h2></div><div class="panel-body"><div class="grid">${[['Daily','Daily'],['Weekly','Weekly'],['Monthly','Monthly'],['Custom','Programme duration']].map(([period,label])=>`<label class="label">${label} cap per user (₹)<input type="number" min="0" step="0.01" data-incentive-cap="${period}" value="${esc(incentiveCaps(draft)[period]??'')}" placeholder="No cap"></label>`).join('')}</div><p class="quiet">The cap matching the programme’s evaluation period applies to combined lump sum and rate earnings. Each evaluation period starts with a fresh cap. Leave empty for no cap; 0 allows no earnings. Managers cannot override this limit.</p></div></section><section class="panel"><div class="panel-head"><h2>Conditions explanation</h2></div><div class="panel-body"><p class="quiet">Default bullets for incentives. Managers can edit these.</p>${explanationRows(draft,true)}</div></section>`+'<div class="savebar">').replaceAll('Primary Field','Main parameter').replaceAll('Other Fields','Secondary parameters').replaceAll('Payout Field','Payout parameter');return html;};
// The manager now owns independent milestone behaviours; remove the obsolete combined matrix selector.
matrixControls=function(){return '<p class="quiet">Managers configure milestone lump sums and rates, then choose slab behaviour and rate behaviour independently. Invalid combinations are disabled.</p>';};
const milestoneAdminBind=bind;bind=function(){milestoneAdminBind();if(role==='admin'&&document.getElementById('msAddExplanation'))bindExplanationRows(draft);for(const [id,key,preview] of [['msCardIcon','icon','msIconSample'],['msCoinIcon','milestone','msCoinSample']]){const el=document.getElementById(id);if(el)el.onchange=()=>uploadIncentiveIcon(el,key,preview);}document.querySelectorAll('[data-ms-display]').forEach(el=>el.oninput=()=>{const k=el.dataset.msDisplay;draft.measureDisplay[k]||=measure(k);draft.measureDisplay[k][el.dataset.msWord]=el.type==='number'?Number(el.value):el.value;});};
const milestoneAdminSave=saveConfig;saveConfig=function(){if(Object.values(incentiveCaps(draft)).some(v=>v!=null&&v!==''&&(!Number.isFinite(Number(v))||Number(v)<0))){toast('Enter non-negative caps or leave them empty.');return false;}draft.earningCaps={...incentiveCaps(draft)};delete draft.earningCap;if(!draft.presentation?.icon?.trim()||!draft.presentation?.milestone?.trim()){toast('Enter both the card icon and milestone coin icon.');return false;}for(const m of Object.values(draft.measureDisplay||{})){if(['label','unit','plural','short'].some(k=>!String(m[k]||'').trim())||m.short.length>4||!Number.isFinite(m.closeGap)||m.closeGap<0){toast('Complete the measure display words and use a non-negative daily gap.');return false;}}const displays=structuredClone(draft.measureDisplay||{});const success=milestoneAdminSave();if(success){for(const [id,m] of Object.entries(displays)){const f=fby(id);if(f)f.display=m;}milestonePersist();render();}return success;};
// Keep existing records and IDs; only add the new representation, without replacing saved configurations.
const milestoneUpdateRule=updateRule;
updateRule=function(...args){milestoneUpdateRule(...args);if(programEdit&&document.getElementById('msLiveCard'))refreshMilestonePreview();};
summary=function(){return `<dl><dt>INCENTIVE TYPE</dt><dd>${esc(draft.name||'New incentive type')}</dd><dt>MAIN PARAMETER</dt><dd>${esc(fname(draft.primary))}</dd><dt>SECONDARY PARAMETERS</dt><dd>${draft.others.map(fname).map(esc).join(', ')||'None'}</dd><dt>REWARDS AVAILABLE</dt><dd>${draft.payouts.map(x=>x==='Variable'?'Rate':'Lumpsum').join(' · ')}</dd><dt>BEHAVIOUR</dt><dd>Top milestone only or every milestone crossed.<br>Rate from this milestone or from the first unit, where valid.</dd><dt>ENTITY CARD ICONS</dt><dd>${incentiveIcon(draft.presentation||{},'icon')} · ${incentiveIcon(draft.presentation||{},'milestone')}</dd></dl>`;};

render();
function incentiveIcon(display,key){const src=display[key+'Svg'];return typeof src==='string'&&src.startsWith('data:image/svg+xml,')?`<img class="ms-svg-icon" src="${esc(src)}" alt="">`:esc(display[key]||(key==='icon'?'🎁':'₹'));}
function validatedIconSvg(source){if(/<!DOCTYPE|<!ENTITY/i.test(source))throw Error('Choose a self-contained SVG without external declarations.');const doc=new DOMParser().parseFromString(source,'image/svg+xml'),root=doc.documentElement;if(doc.querySelector('parsererror')||root.localName!=='svg'||root.namespaceURI!=='http://www.w3.org/2000/svg')throw Error('The file is not a valid SVG.');for(const el of [root,...root.querySelectorAll('*')]){if(['script','foreignobject','iframe','object','embed','image','animate','animatetransform','animatemotion','set'].includes(el.localName.toLowerCase()))throw Error('Use a static SVG with no scripts or embedded content.');for(const a of el.attributes){if(/^on/i.test(a.name)||(/href$/i.test(a.name)&&a.value&&!a.value.startsWith('#')))throw Error('SVG icons cannot contain active content or external links.');if(/url\(\s*['"]?(?!#)/i.test(a.value))throw Error('SVG icons must use local shapes and colours.');}if(el.localName==='style'&&(/@import|url\(/i.test(el.textContent)))throw Error('SVG styles cannot load external content.');}return 'data:image/svg+xml,'+encodeURIComponent(new XMLSerializer().serializeToString(root));}
async function uploadIncentiveIcon(input,key,preview){const file=input.files?.[0],owner=draft;if(!file)return;try{if(!/\.svg$/i.test(file.name))throw Error('Choose an SVG file.');if(file.size>100*1024)throw Error('Choose an SVG under 100 KB.');const src=validatedIconSvg(await file.text());if(draft!==owner)return;owner.presentation[key+'Svg']=src;owner.presentation[key+'File']=file.name;document.getElementById(preview).innerHTML=incentiveIcon(owner.presentation,key);document.getElementById(key==='icon'?'msCardFile':'msCoinFile').textContent=file.name;const summaryEl=document.getElementById('summary');if(summaryEl)summaryEl.innerHTML=summary();}catch(e){toast(e.message);input.value='';}}

document.addEventListener('input',e=>{if(e.target.dataset.incentiveCap&&draft){draft.earningCaps={...incentiveCaps(draft),[e.target.dataset.incentiveCap]:e.target.value===''?null:Number(e.target.value)};}});
